<?php
declare(strict_types=1);
define('BASE_PATH',dirname(__DIR__));
spl_autoload_register(static function(string $class):void{if(str_starts_with($class,'App\\'))require BASE_PATH.'/app/'.str_replace('\\','/',substr($class,4)).'.php';});
function automaticCheck(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
function automaticStudents(array $counts):array{
    $rows=[];$id=0;
    foreach($counts as $key=>$count)for($i=1;$i<=$count;$i++)$rows[]=['student_id'=>++$id,'group_key'=>$key,'course_id'=>ord($key),'normalized_roll_no'=>$key.sprintf('%03d',$i),'school_id'=>$key==='D'?2:1,'school_code'=>'ICT','programme_id'=>ord($key),'programme_code'=>$key,'programme_name'=>$key,'batch_id'=>1,'batch_label'=>'2026-2030','programme_duration_semesters'=>8,'semester'=>in_array($key,['B','D'],true)?5:1];
    return $rows;
}
function automaticSeats(int $rooms=3,int $rows=20):array{
    $pool=[];$id=0;for($room=1;$room<=$rooms;$room++)for($column=1;$column<=2;$column++)for($row=1;$row<=$rows;$row++)$pool[]=['seat_id'=>++$id,'room_id'=>$room,'school_id'=>$room===4?2:1,'column_no'=>$column,'row_no'=>$row];return $pool;
}
$planner=new App\Seating\AutomaticPairedCohortPlanner();$students=automaticStudents(['A'=>30,'B'=>60,'C'=>30]);$seats=automaticSeats();
$pairs=[['left'=>'A','right'=>'B','room_ids'=>[2]],['left'=>'B','right'=>'C','room_ids'=>[2]]];
$plan=$planner->plan($students,$seats,$pairs);
automaticCheck(count($plan['assigned'])===120&&!$plan['unallocated'],'Carry-over pairing did not seat all students.');
automaticCheck(count(array_unique(array_column($plan['assigned'],'student_id')))===120,'A student was seated twice.');
automaticCheck(count(array_unique(array_column($plan['assignmentSeats'],'seat_id')))===120,'A seat was used twice.');
automaticCheck($plan['assignmentSeats'][0]['room_id']===2,'Preferred room ignored.');
automaticCheck($plan['assignmentSeats'][40]['room_id']===1,'Full preferred room did not fall back.');
automaticCheck($plan['assignmentSeats'][60]['room_id']===1,'Next pair failed to share remaining room capacity.');
automaticCheck($plan['rules']['pairings'][1]['matched_count']===30,'Remaining branch count incorrect.');
foreach($plan['assigned'] as $i=>$student){$seat=$plan['assignmentSeats'][$i];automaticCheck(App\Seating\PairedCohortPlanner::allows($plan['rules'],$student['student_id'],$seat['room_id'],$seat['column_no'],$seat['seat_id']),'Saved seat validation rejected generated assignment.');}
automaticCheck(!App\Seating\PairedCohortPlanner::allows($plan['rules'],1,2,2,$plan['assignmentSeats'][1]['seat_id']),'Manual move bypassed saved seat group.');
$reordered=$planner->plan($students,$seats,array_reverse($pairs));
automaticCheck($reordered['assigned'][0]['group_key']==='B','Pair priority ignored.');
$noPreference=$planner->plan($students,$seats,[['left'=>'A','right'=>'B']]);
automaticCheck($noPreference['assignmentSeats'][0]['room_id']===1,'Saved default room priority ignored.');
$roomOrder=$planner->plan($students,$seats,[['left'=>'A','right'=>'B','room_ids'=>[3,2]]]);
automaticCheck($roomOrder['assignmentSeats'][0]['room_id']===3,'Explicit room priority ignored.');
$two=automaticStudents(['A'=>30,'B'=>60]);
$review=$planner->plan($two,$seats,[['left'=>'A','right'=>'B']],false);
automaticCheck(count($review['assigned'])===60&&count($review['unallocated'])===30,'Review choice did not retain leftover students.');
$solo=$planner->plan($two,$seats,[['left'=>'A','right'=>'B']],true);
automaticCheck(count($solo['assigned'])===90&&!$solo['unallocated'],'Automatic final cohort choice failed.');
$single=$planner->plan(automaticStudents(['B'=>10]),$seats,[],true);
automaticCheck(count($single['assigned'])===10,'Single-cohort session failed.');
$multi=$planner->plan(automaticStudents(['A'=>30,'B'=>60,'C'=>30]),$seats,[['left'=>'A','right'=>'B']],true);
automaticCheck(count($multi['assigned'])===60&&count($multi['unallocated'])===60,'Two remaining cohorts were seated without a pair.');
$short=$planner->plan($students,automaticSeats(1,10),[['left'=>'A','right'=>'B'],['left'=>'B','right'=>'C']],true);
automaticCheck(count($short['assigned'])===20&&count($short['unallocated'])===100,'Capacity shortage lost or duplicated students.');
$blocked=$seats;array_shift($blocked);
$geometry=$planner->plan($two,$blocked,[['left'=>'A','right'=>'B']],true);
automaticCheck(count($geometry['assigned'])===90,'Blocked seat prevented valid overflow allocation.');
$reject=static function(array $students,array $seats,array $pairs)use($planner):void{try{$planner->plan($students,$seats,$pairs);throw new LogicException('Invalid pairing accepted.');}catch(RuntimeException $e){}};
$reject($students,$seats,[['left'=>'A','right'=>'B'],['left'=>'A','right'=>'C']]);
$reject(automaticStudents(['A'=>1,'D'=>1]),automaticSeats(4),[['left'=>'A','right'=>'D']]);
$reject($students,$seats,[['left'=>'A','right'=>'A']]);
$reject($students,$seats,[['left'=>'A','right'=>'B','room_ids'=>[999]]]);
$sameBranch=automaticStudents(['A'=>4,'B'=>4]);
foreach($sameBranch as &$student)$student['programme_id']=1;unset($student);
$reject($sameBranch,$seats,[['left'=>'A','right'=>'B']]);
$isolated=$planner->plan(automaticStudents(['A'=>4]),automaticSeats(1,4),[],true);
automaticCheck(count($isolated['assigned'])===4&&count($isolated['unallocated'])===0,'Solo branch did not leave its neighbour seats empty.');
$crowded=$planner->plan(automaticStudents(['A'=>8]),automaticSeats(1,4),[],true);
automaticCheck(count($crowded['assigned'])===4&&count($crowded['unallocated'])===4,'Solo branch occupied both sides of a desk.');
// Consecutive slots from different pairs may share a branch at their boundary.
$wide=[];$seatId=0;for($column=1;$column<=8;$column++)$wide[]=['seat_id'=>++$seatId,'room_id'=>1,'school_id'=>1,'columns_count'=>8,'column_no'=>$column,'row_no'=>1];
$boundary=$planner->plan(automaticStudents(['A'=>1,'B'=>2,'C'=>1]),$wide,[['left'=>'A','right'=>'B'],['left'=>'B','right'=>'C']]);
$neighbours=App\Seating\BranchSeparation::neighbours($wide);$occupied=[];
foreach($boundary['assigned'] as $i=>$student)$occupied[$boundary['assignmentSeats'][$i]['seat_id']]=$student['programme_id'];
foreach($occupied as $id=>$programme)foreach($neighbours[$id]??[] as $other=>$_)automaticCheck(($occupied[$other]??null)!==$programme,'Adjacent pairs placed the same branch side by side.');
automaticCheck(count($boundary['assigned'])===4,'Could not swap a pair to avoid a boundary conflict.');
$samePaper=automaticStudents(['A'=>2,'B'=>2]);foreach($samePaper as &$student)$student['course_id']=500;unset($student);
$reject($samePaper,$seats,[['left'=>'A','right'=>'B']]);
$commonPaper=automaticStudents(['A'=>1,'B'=>1,'C'=>1,'D'=>1]);
foreach($commonPaper as &$student){$student['school_id']=1;if(in_array($student['group_key'],['B','C'],true))$student['course_id']=500;}unset($student);
$paperBoundary=$planner->plan($commonPaper,$wide,[['left'=>'A','right'=>'B'],['left'=>'C','right'=>'D']]);
$occupiedPapers=[];foreach($paperBoundary['assigned'] as $i=>$student)$occupiedPapers[$paperBoundary['assignmentSeats'][$i]['seat_id']]=$student['course_id'];
foreach($occupiedPapers as $id=>$paper)foreach($neighbours[$id]??[] as $other=>$_)automaticCheck(($occupiedPapers[$other]??null)!==$paper,'Different branches with the same paper were neighbours.');
automaticCheck(count($paperBoundary['assigned'])===4,'Paper-aware pair orientation failed.');
automaticCheck($paperBoundary['rules']['paper_separation']===true,'Paper rule was not saved.');
$sameYear=automaticStudents(['A'=>1,'B'=>1]);foreach($sameYear as &$student)$student['semester']=1;unset($student);
automaticCheck(count($planner->plan($sameYear,$seats,[['left'=>'A','right'=>'B']])['assigned'])===2,'Different branches in the same year were rejected.');
$yearGroups=[['study_year'=>1,'final_year'=>4],['study_year'=>3,'final_year'=>4],['study_year'=>2,'final_year'=>4],['study_year'=>4,'final_year'=>4],['study_year'=>5,'final_year'=>5]];
automaticCheck(App\Seating\YearPairingPolicy::allows($yearGroups[0],$yearGroups[1]),'First/third-year rule failed.');
automaticCheck(App\Seating\YearPairingPolicy::allows($yearGroups[2],$yearGroups[3]),'Second/fourth-year rule failed.');
automaticCheck(App\Seating\YearPairingPolicy::allows($yearGroups[2],$yearGroups[4]),'Final year ignored programme duration.');
automaticCheck(!App\Seating\YearPairingPolicy::allows($yearGroups[0],$yearGroups[3]),'First/final-year pair was incorrectly allowed.');
$sameCode=automaticStudents(['A'=>1,'B'=>1]);foreach($sameCode as &$student)$student['course_code']=$student['group_key']==='A'?'MATH 101':'math101';unset($student);$reject($sameCode,$seats,[['left'=>'A','right'=>'B']]);
$unmatched=$planner->plan(automaticStudents(['A'=>30,'C'=>30]),$seats,[],false,true);
automaticCheck(count($unmatched['assigned'])===60&&!$unmatched['unallocated'],'Multiple unmatched groups did not use alternating columns.');
foreach($unmatched['assignmentSeats'] as $seat)automaticCheck($seat['column_no']===1,'Fallback filled a partner column.');
automaticCheck(count($unmatched['rules']['empty_partner_columns'])===3,'Empty partner columns were not saved.');
$fallbackShort=$planner->plan(automaticStudents(['A'=>30,'C'=>30]),automaticSeats(1,20),[],false,true);
automaticCheck(count($fallbackShort['assigned'])===20&&count($fallbackShort['unallocated'])===40,'Half-capacity fallback lost its shortage.');
$mixed=$planner->plan($students,$seats,[['left'=>'A','right'=>'B']],false,true);
automaticCheck(count($mixed['assigned'])===80&&count($mixed['unallocated'])===40,'Fallback reused a partially paired column.');
foreach($mixed['assignmentSeats'] as $seat)automaticCheck(empty($mixed['rules']['empty_partner_columns'][$seat['room_id']][$seat['column_no']]),'A reserved empty column was occupied.');
$converted=$planner->plan($sameBranch,$seats,[['left'=>'A','right'=>'B']],false,true);
automaticCheck(count($converted['assigned'])===8&&!$converted['unallocated'],'Same-branch pairing did not convert to spaced seating.');
automaticCheck($converted['rules']['converted_pairings'][0]['reason']==='same_branch','Converted same-branch pairing was not recorded.');
foreach($converted['assignmentSeats'] as $seat)automaticCheck($seat['column_no']===1,'Same-branch fallback filled a partner column.');
$convertedPaper=$planner->plan($samePaper,$seats,[['left'=>'A','right'=>'B']],false,true);
automaticCheck(count($convertedPaper['assigned'])===4&&$convertedPaper['rules']['converted_pairings'][0]['reason']==='shared_paper','Shared-paper selection failed to use safe spacing.');
$duplicateSelection=$planner->plan(automaticStudents(['A'=>4]),$seats,[['left'=>'A','right'=>'A']],false,true);
automaticCheck(count($duplicateSelection['assigned'])===4,'A stale duplicate group selection lost or duplicated students.');
echo "Automatic paired seating: PASS (30/60 carry-over, balanced reservations, shared rooms, priorities, fallback, both remainder choices, shortages, blocked seats, school isolation, saved validation)\n";
